<?php

declare(strict_types=1);

namespace Tests\Ewo;

use App\Libraries\AdminIdentity;
use App\Libraries\LegacyPassword;
use App\Models\AuthRepository;
use CodeIgniter\Database\BaseConnection;
use CodeIgniter\Session\SessionInterface;
use CodeIgniter\Test\CIUnitTestCase;
use Config\Database;

final class AdminIdentityTest extends CIUnitTestCase
{
    // Synthetic password hash generated by the portable mode of CI3 EWO Bcrypt.
    private const PORTABLE_HASH = '$P$BjQ7HPZEdkLppNPiAcMg0viYbxnKDs1';
    private BaseConnection $database;
    private array $sessionData = [];

    protected function setUp(): void
    {
        parent::setUp();
        $this->database = Database::connect([
            'DBDriver' => 'SQLite3',
            'database' => ':memory:',
            'DBPrefix' => '',
        ], false);
        $this->database->query('CREATE TABLE users (id INTEGER PRIMARY KEY, email TEXT, password TEXT,
            status INTEGER, role TEXT, role_id INTEGER, last_seen TEXT, ip_address TEXT)');
        $this->database->query('CREATE TABLE roles_permissions (role TEXT PRIMARY KEY, admin_panel INTEGER, add_post INTEGER)');
        $this->database->query('CREATE TABLE users_logs (user_id INTEGER, last_seen TEXT, ip_address TEXT)');
        $this->database->query('CREATE TABLE general_settings (id INTEGER PRIMARY KEY, timezone TEXT, site_lang INTEGER)');
        $this->database->table('general_settings')->insert(['id'=>1, 'timezone'=>'Asia/Jakarta', 'site_lang'=>1]);
        $this->database->table('roles_permissions')->insertBatch([
            ['role'=>'admin', 'admin_panel'=>0, 'add_post'=>0],
            ['role'=>'staff', 'admin_panel'=>1, 'add_post'=>0],
            ['role'=>'reporter', 'admin_panel'=>1, 'add_post'=>1],
        ]);
        $this->database->table('users')->insertBatch([
            ['id'=>1,'email'=>'staff@example.test','password'=>self::PORTABLE_HASH,'status'=>1,'role'=>'staff','role_id'=>4],
            ['id'=>2,'email'=>'blocked@example.test','password'=>self::PORTABLE_HASH,'status'=>0,'role'=>'staff','role_id'=>4],
        ]);
    }

    protected function tearDown(): void
    {
        $this->database->close();
        parent::tearDown();
    }

    public function testLegacyHashFormats(): void
    {
        $passwords = new LegacyPassword();
        $bcrypt = password_hash('fixture-password', PASSWORD_BCRYPT);

        self::assertTrue($passwords->verify('fixture-password', self::PORTABLE_HASH));
        self::assertTrue($passwords->verify('fixture-password', '$H$' . substr(self::PORTABLE_HASH, 3)));
        self::assertTrue($passwords->verify('fixture-password', $bcrypt));
        self::assertFalse($passwords->verify('bad-password', $bcrypt));
        self::assertFalse($passwords->verify('bad-password', self::PORTABLE_HASH));
        self::assertFalse($passwords->verify('fixture-password', '$P$'));
        self::assertFalse($passwords->verify('fixture-password', '*0'));
    }

    public function testSuccessfulLoginAndActivity(): void
    {
        $auth = $this->identity(true);
        self::assertSame('', $auth->authenticate('staff@example.test', 'fixture-password', '127.0.0.1'));
        self::assertTrue($this->sessionData['vr_sess_logged_in']);
        self::assertSame(4, (int) $this->sessionData['vr_sess_user_role_id']);
        self::assertSame('fixture-key', $this->sessionData['vr_sess_app_key']);
        $user = $auth->currentUser();
        self::assertSame(1, (int) $user['id']);
        $auth->recordActivity($user, '127.0.0.1');
        $activity = $this->database->table('users_logs')->get()->getRowArray();
        self::assertSame('127.0.0.1', $activity['ip_address']);
        self::assertSame($activity['last_seen'], $auth->currentUser()['last_seen']);
        self::assertSame(self::PORTABLE_HASH, $auth->currentUser()['password']);
    }

    public function testFailedAndBlockedLoginDoNotCreateSession(): void
    {
        $auth = $this->identity(false);
        self::assertSame('login_error', $auth->authenticate('staff@example.test', 'wrong', '127.0.0.1'));
        self::assertSame('login_error', $auth->authenticate('missing@example.test', 'wrong', '127.0.0.1'));
        self::assertSame('message_ban_error', $auth->authenticate('blocked@example.test', 'fixture-password', '127.0.0.1'));
        self::assertNull($auth->currentUser());
        self::assertSame([], $this->sessionData);
    }

    public function testPermissionReadsRoleFlagAndAdminOverride(): void
    {
        $auth = $this->identity(false);
        self::assertTrue($auth->allows(['role'=>'admin'], 'admin_panel'));
        self::assertTrue($auth->allows(['role'=>'staff'], 'admin_panel'));
        self::assertTrue($auth->allows(['role'=>'reporter'], 'add_post'));
        self::assertFalse($auth->allows(['role'=>'staff'], 'add_post'));
        self::assertFalse($auth->allows(['role'=>'unknown'], 'add_post'));
    }

    private function identity(bool $shouldRotate): AdminIdentity
    {
        $session = $this->createMock(SessionInterface::class);
        $session->expects($shouldRotate ? self::once() : self::never())->method('regenerate')->with(true);
        $session->method('set')->willReturnCallback(function (array $data): void {
            $this->sessionData = $data;
        });
        $session->method('get')->willReturnCallback(fn(string $key) => $this->sessionData[$key] ?? null);

        return new AdminIdentity(new AuthRepository($this->database), $session, new LegacyPassword(), 'fixture-key');
    }
}
